head.b:skin:
/* 
THEME: Medical Academic Framework (Emerald & Velvet Edition)
VERSION: 2.0 - Multilingual Support
*/
:root {
    --emerald: #044d44;
    --gold: #d4af37;
    --velvet: #1a0b12;
    --card-bg: #ffffff;
    --text-main: #333333;
}
body {
    background-color: var(--velvet);
    color: var(--text-main);
    font-family: 'Inter', 'Segoe UI', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--emerald), #022b26);
    color: var(--gold);
    padding: 40px 20px;
    text-align: center;
    border-bottom: 3px solid var(--gold);
}
.main-container {
    max-width: 900px;
    margin: -40px auto 50px;
    padding: 20px;
}
.academic-card {
    background: var(--card-bg);
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
    padding: 30px;
    margin-bottom: 25px;
    border-left: 5px solid var(--gold);
}
.input-group { margin-bottom: 20px; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    color: var(--emerald);
    font-size: 14px;
}
.input-group input, .input-group textarea, .lang-select {
    width: 100%;
    padding: 12px;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fdfdfd;
}
.input-group textarea { height: 100px; resize: vertical; }

/* Style for Language Selector */
.lang-options {
    display: flex;
    gap: 20px;
    margin-top: 5px;
}
.lang-item {
    display: flex;
    align-items: center;
    cursor: pointer;
    font-weight: 500;
}
.lang-item input { width: auto; margin-right: 8px; }

h2 { color: var(--emerald); border-bottom: 1px solid #eee; padding-bottom: 10px; margin-top: 0; }

.copy-btn {
    background: var(--gold);
    color: var(--velvet);
    border: none;
    padding: 15px 20px;
    cursor: pointer;
    font-weight: bold;
    border-radius: 4px;
    width: 100%;
    transition: 0.3s;
    font-size: 16px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.copy-btn:hover { background: #b8962d; transform: translateY(-2px); }
footer { text-align: center; color: #888; padding: 20px; font-size: 12px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "[No Title Provided]";
    var notes = document.getElementById("inputNotes").value || "[No Notes Provided]";

    // Cek pilihan bahasa
    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    // Injeksi data
    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    // Copy ke Clipboard
    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("Prompt (" + (selectedLang === 'id' ? 'Bahasa Indonesia' : 'English') + ") berhasil disalin!");
}
